(26061, 'John 11:14', 'John', 11, 14, 'نو عیسی هغوی ته ښکاره وویل: «ایلعازر مړ شوی دی.', 'نو عیسی هغوی ته شکاره وویل: «ایلعازر مر شوی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26062, 'John 11:15', 'John', 11, 15, 'خو زه ستاسو په خاطر خوشحاله یم چې هلته نه وم، ځکه چې تاسو به اوس په رښتیا ایمان راوړئ. راځئ چې هغه ته ورشو.»', 'خو زه ستاسو په خاطر خوشحاله یم چې هلته نه وم، جکه چې تاسو به اوس په رشتیا ایمان راوری. راجی چې هغه ته ورشو.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26063, 'John 11:16', 'John', 11, 16, 'توما چې د غبرګوني په نوم هم یادېده، نورو شاګردانو ته وویل: «راځئ چې مونږ هم لاړ شو او د هغه سره مړه شو.» عیسی قیامت او ژوندون دی', 'توما چې د غبرګونی په نوم هم یادېده، نورو شاګردانو ته وویل: «راجی چې مونز هم لار شو او د هغه سره مره شو.» عیسی قیامت او ژوندون دی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26064, 'John 11:17', 'John', 11, 17, 'کله چې عیسی هغه ځای ته ورسېده، څلور ورځې کېدلې چې د ایلعازر مړی په قبر کې ایښودل شوی ؤ.', 'کله چې عیسی هغه جای ته ورسېده، چلور ورجې کېدلې چې د ایلعازر مری په قبر کې ایشودل شوی و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26065, 'John 11:18', 'John', 11, 18, 'بیت‌عنیا د اورشلیم نه شاوخوا درې کیلومتره لېرې ؤ', 'بیت‌عنیا د اورشلیم نه شاوخوا درې کیلومتره لېرې و', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26066, 'John 11:19', 'John', 11, 19, 'او د اورشلیم نه د یهودیې ډېر خلک مرتا او مریم ته راغلي وو چې د هغوی د ورور د مړینې په خاطر ورته تسلي ورکړي،', 'او د اورشلیم نه د یهودیې دېر خلک مرتا او مریم ته راغلی وو چې د هغوی د ورور د مرینې په خاطر ورته تسلی ورکری،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26067, 'John 11:20', 'John', 11, 20, 'نو کله چې مرتا د عیسی د راتللو څخه خبره شوه، د هغه مخې ته ورغله، خو مریم په کور کې پاتې شوه.', 'نو کله چې مرتا د عیسی د راتللو چخه خبره شوه، د هغه مخې ته ورغله، خو مریم په کور کې پاتې شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26068, 'John 11:21', 'John', 11, 21, 'مرتا عیسی ته وویل: «استاذه، که ته دلته وای، نو زما ورور به نه وای مړ شوی.', 'مرتا عیسی ته وویل: «استاذه، که ته دلته وای، نو زما ورور به نه وای مر شوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26069, 'John 11:22', 'John', 11, 22, 'خو زه اوس هم په دې پوهېږم چې که ته د خدای څخه هرڅه وغواړې، نو خدای به یې درکړي.»', 'خو زه اوس هم په دې پوهېزم چې که ته د خدای چخه هرچه وغوارې، نو خدای به یې درکری.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26070, 'John 11:23', 'John', 11, 23, 'عیسی هغې ته وویل: «ستا ورور به بېرته راژوندی شي.»', 'عیسی هغې ته وویل: «ستا ورور به بېرته راژوندی شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26071, 'John 11:24', 'John', 11, 24, 'مرتا وویل: «زه پوهېږم چې هغه به د قیامت په ورځ راژوندی شي.»', 'مرتا وویل: «زه پوهېزم چې هغه به د قیامت په ورج راژوندی شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26072, 'John 11:25', 'John', 11, 25, 'عیسی هغې ته وویل: «زه قیامت او ژوندون یم. که څوک په ما باندې ایمان راوړي که هغه مړ هم شي، خو بیا به هم ژوندی وي،', 'عیسی هغې ته وویل: «زه قیامت او ژوندون یم. که چوک په ما باندې ایمان راوری که هغه مر هم شی، خو بیا به هم ژوندی وی،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26073, 'John 11:26', 'John', 11, 26, 'او که څوک ژوندی وي او په ما باندې ایمان راوړي، نو هغه به هېڅکله هم مړ نه شي. ایا په دې باندې باور کوې؟»', 'او که چوک ژوندی وی او په ما باندې ایمان راوری، نو هغه به هېچکله هم مر نه شی. ایا په دې باندې باور کوې؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26074, 'John 11:27', 'John', 11, 27, 'هغې وویل: «هو، استاذه! زه په دې ایمان لرم چې ته مسیح یعنې د خدای زوی یې، د چا په هکله چې خدای ویلي دي چې هغه باید نړۍ ته راشي.» عیسی ژاړي', 'هغې وویل: «هو، استاذه! زه په دې ایمان لرم چې ته مسیح یعنې د خدای زوی یې، د چا په هکله چې خدای ویلی دی چې هغه باید نری ته راشی.» عیسی ژاری', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26075, 'John 11:28', 'John', 11, 28, 'کله چې مرتا دا خبره وکړه، نو لاړه او خپلې خور ته یې غږ وکړ او په پټه یې ورته وویل: «استاذ راغلی دی او تا غواړي.»', 'کله چې مرتا دا خبره وکره، نو لاره او خپلې خور ته یې غز وکر او په پته یې ورته وویل: «استاذ راغلی دی او تا غواری.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26076, 'John 11:29', 'John', 11, 29, 'کله چې مریم دا واورېدل، نو زر راپاڅېدله او عیسی ته ورغله.', 'کله چې مریم دا واورېدل، نو زر راپاچېدله او عیسی ته ورغله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26077, 'John 11:30', 'John', 11, 30, 'عیسی لا کلي ته رسېدلی نه ؤ او لا په هماغه ځای کې ؤ چې مرتا یې لیدلو ته ورغلې وه.', 'عیسی لا کلی ته رسېدلی نه و او لا په هماغه جای کې و چې مرتا یې لیدلو ته ورغلې وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26078, 'John 11:31', 'John', 11, 31, 'کوم خلک چې مریم ته د تسلۍ ورکولو دپاره راغلي وو او د هغې په کور کې وو، نو کله یې چې ولیدل چې هغه په بیړه له کوره وځي نو هغې پسې روان شول. هغوی فکر کاوه چې هغه قبر ته روانه ده چې هلته وژاړي.', 'کوم خلک چې مریم ته د تسلی ورکولو دپاره راغلی وو او د هغې په کور کې وو، نو کله یې چې ولیدل چې هغه په بیره له کوره وجی نو هغې پسې روان شول. هغوی فکر کاوه چې هغه قبر ته روانه ده چې هلته وژاری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26079, 'John 11:32', 'John', 11, 32, 'مریم هغه ځای ته ورسېدله چې عیسی په کې ؤ او څنګه یې چې هغه ولیده، نو پښو ته یې پرېوتله او ویې ویل: «استاذه، که ته دلته وای، نو زما ورور به نه وای مړ شوی.»', 'مریم هغه جای ته ورسېدله چې عیسی په کې و او چنګه یې چې هغه ولیده، نو پشو ته یې پرېوتله او ویې ویل: «استاذه، که ته دلته وای، نو زما ورور به نه وای مر شوی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(26080, 'John 11:33', 'John', 11, 33, 'کله چې عیسی هغه ولیدله چې ژاړي او همدارنګه کوم خلک چې د هغې سره راغلي وو هم ژاړي، نو سوړ اوسېلی یې وویست او ډېر خفه شو', 'کله چې عیسی هغه ولیدله چې ژاری او همدارنګه کوم خلک چې د هغې سره راغلی وو هم ژاری، نو سور اوسېلی یې وویست او دېر خفه شو', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(26081, 'John 11:34', 'John', 11, 34, 'او د هغوی نه یې پوښتنه وکړه: «د هغه قبر چېرته دی؟» هغوی ځواب ورکړ: «ښاغلیه، راشه او ویې ګوره.»', 'او د هغوی نه یې پوشتنه وکره: «د هغه قبر چېرته دی؟» هغوی جواب ورکر: «شاغلیه، راشه او ویې ګوره.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_11_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
